export type RngTrace = { readonly "draws": readonly (RngDraw)[]; readonly "state": "observed" } | { readonly "state": "unknown" } | { readonly "reason": UnavailableCause; readonly "state": "unavailable" };
export type RoleBinding = { readonly "entity_id": EntityId; readonly "role": Key };
export type RoomDefinition = { readonly "actions"?: readonly (ActionContribution)[]; readonly "description": TextKey; readonly "details"?: Readonly<Record<string, InspectableDetail>>; readonly "exits": { readonly "down"?: Connection; readonly "east"?: Connection; readonly "north"?: Connection; readonly "south"?: Connection; readonly "up"?: Connection; readonly "west"?: Connection }; readonly "key": Key; readonly "title": TextKey; readonly "variants"?: readonly (DescriptionVariant)[] };
export type RunHeader = { readonly "fault_schedule": { readonly "digest": ContentHash; readonly "state": "identified" } | { readonly "reason": UnavailableCause; readonly "state": "unavailable" }; readonly "initial_state": { readonly "state": "fresh" } | { readonly "reason": UnavailableCause; readonly "state": "unavailable" }; readonly "world_context_id": WorldContextId };
export type RunIds = { readonly "content_hash": ContentHash; readonly "kernel_version": KernelVersion; readonly "run_id": StoryRunId; readonly "seed": RngState };
export type ScopedFact = { readonly "fact": DefinitionRef; readonly "fact_version": number; readonly "scope": StateScope; readonly "subject_id"?: EntityId; readonly "value": FactValue };
export type StateDelta = { readonly "ops": readonly (DeltaOp)[] };
export type StateScope = { readonly "character_id": CharacterId; readonly "kind": "player" } | { readonly "kind": "party"; readonly "party_id": PartyId } | { readonly "kind": "instance"; readonly "world_context_id": WorldContextId } | { readonly "kind": "realm"; readonly "realm_id": RealmId };
export type StoryRun = { readonly "account_id"?: AccountId; readonly "parent_run_id"?: StoryRunId; readonly "profile_id": LocalProfileId; readonly "release": CartridgeRelease; readonly "run_id": StoryRunId };
export type StoryRunId = string & { readonly __brand: 'StoryRunId' };
export type TargetResolution = { readonly "kind": "none" } | { readonly "kind": "unique"; readonly "target_id": EntityId } | { readonly "candidate_ids": readonly (EntityId)[]; readonly "kind": "ambiguous" };
export type TargetSpec = { readonly "kind": "none" } | { readonly "kind": "entity"; readonly "scopes": readonly ("self" | "inventory" | "room_contents" | "room_occupants")[] };
export type TargetUnresolved = { readonly "after_ordinal": number; readonly "candidates": number; readonly "outcome": "none" | "ambiguous"; readonly "room": DefinitionRef; readonly "words": readonly (LookupWord)[] };
