export type TraceDecision = { readonly "delta_digest": ContentHash; readonly "kind": "accepted"; readonly "outcome": Key; readonly "rng": RngTrace; readonly "rng_state": RngState } | { readonly "error": GameError; readonly "kind": "rejected" } | { readonly "code": ErrorCode; readonly "kind": "fault"; readonly "target"?: MutationTarget };
export type TraceEntry = { readonly "command": Command; readonly "commit": CommitOutcome; readonly "decision": TraceDecision; readonly "ordinal": number };
export type UnavailableCause = "not_applicable" | "not_collected";
export type UnavailableReason = { readonly "code": ErrorCode; readonly "message"?: Text };
export type VersionedPolicy = { readonly "policy_version": 1; readonly "root": Policy };
export type WorkIds = { readonly "pull_request": number };
export type WorldContextId = string & { readonly __brand: 'WorldContextId' };
